package com.primehr.migration;
import org.junit.jupiter.api.Test; import java.io.*; import java.nio.charset.StandardCharsets; import java.util.Set; import static org.assertj.core.api.Assertions.assertThat;
class SuccessionV47MigrationParityTest {
 @Test void pairedMigrationsHaveMatchingGovernanceStructures() throws Exception {String p=read("db/migration/postgresql/V47__succession_governance_foundation.sql").toLowerCase(),s=read("db/migration/sqlserver/V47__succession_governance_foundation.sql").toLowerCase();Set<String> names=Set.of("succession_governance_policy","succession_governance_policy_version","succession_readiness_scale","succession_readiness_scale_version","succession_readiness_level","succession_committee_charter","succession_committee_charter_version","succession_committee_member","succession_committee_conflict","uk_succ_policy_code","uk_succ_scale_code","uk_succ_level_code","uk_succ_charter_code","uk_succ_member_employee","ix_succ_policy_effective","ix_succ_scale_effective","ix_succ_level_scale","ix_succ_charter_effective","ix_succ_member_charter","ix_succ_conflict_charter");for(String migration:Set.of(p,s)){assertThat(migration).contains(names.toArray(String[]::new));assertThat(migration).doesNotContain("insert into","delete from","drop table","payroll_transaction","employeeappointment");}}
 private String read(String path)throws IOException{try(var in=getClass().getClassLoader().getResourceAsStream(path)){if(in==null)throw new IOException(path);return new String(in.readAllBytes(),StandardCharsets.UTF_8);}}
}
